package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"time"
)

const tasksFileName = "todos.json"

// Task represents a single todo item.
type Task struct {
	ID        int64     `json:"id"`
	Title     string    `json:"title"`
	Done      bool      `json:"done"`
	CreatedAt time.Time `json:"created_at"`
}

func tasksFilePath() (string, error) {
	exe, err := os.Executable()
	if err != nil {
		return "", err
	}
	// Resolve symlinks so we get the real binary path.
	exe, err = filepath.EvalSymlinks(exe)
	if err != nil {
		return "", err
	}
	dir := filepath.Dir(exe)
	return filepath.Join(dir, tasksFileName), nil
}

func loadTasks(path string) ([]Task, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return []Task{}, nil
		}
		return nil, err
	}
	var tasks []Task
	if err := json.Unmarshal(data, &tasks); err != nil {
		return nil, fmt.Errorf("corrupt tasks file %s: %w", path, err)
	}
	return tasks, nil
}

func saveTasks(path string, tasks []Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

func nextID(tasks []Task) int64 {
	var max int64
	for _, t := range tasks {
		if t.ID > max {
			max = t.ID
		}
	}
	return max + 1
}

func findTask(tasks []Task, id int64) int {
	for i, t := range tasks {
		if t.ID == id {
			return i
		}
	}
	return -1
}

func cmdAdd(args []string) error {
	fs := flag.NewFlagSet("add", flag.ExitOnError)
	fs.Parse(args)
	title := fs.Arg(0)
	if title == "" {
		return fmt.Errorf("usage: todo2 add <title>")
	}

	path, err := tasksFilePath()
	if err != nil {
		return err
	}
	tasks, err := loadTasks(path)
	if err != nil {
		return err
	}

	task := Task{
		ID:        nextID(tasks),
		Title:     title,
		Done:      false,
		CreatedAt: time.Now(),
	}
	tasks = append(tasks, task)
	if err := saveTasks(path, tasks); err != nil {
		return err
	}

	fmt.Printf("Added task #%d: %s\n", task.ID, task.Title)
	return nil
}

func cmdList(args []string) error {
	path, err := tasksFilePath()
	if err != nil {
		return err
	}
	tasks, err := loadTasks(path)
	if err != nil {
		return err
	}

	sort.Slice(tasks, func(i, j int) bool {
		if tasks[i].Done != tasks[j].Done {
			return !tasks[i].Done // pending first
		}
		return tasks[i].CreatedAt.Before(tasks[j].CreatedAt)
	})

	if len(tasks) == 0 {
		fmt.Println("No tasks.")
		return nil
	}
	for _, t := range tasks {
		status := " "
		if t.Done {
			status = "x"
		}
		fmt.Printf("[%s] #%d %s (created %s)\n", status, t.ID, t.Title, t.CreatedAt.Format(time.RFC3339))
	}
	return nil
}

func cmdDone(args []string) error {
	id, err := parseID(args)
	if err != nil {
		return err
	}
	path, err := tasksFilePath()
	if err != nil {
		return err
	}
	tasks, err := loadTasks(path)
	if err != nil {
		return err
	}
	i := findTask(tasks, id)
	if i < 0 {
		return fmt.Errorf("no task with id %d", id)
	}
	tasks[i].Done = true
	if err := saveTasks(path, tasks); err != nil {
		return err
	}
	fmt.Printf("Done task #%d: %s\n", id, tasks[i].Title)
	return nil
}

func cmdRm(args []string) error {
	id, err := parseID(args)
	if err != nil {
		return err
	}
	path, err := tasksFilePath()
	if err != nil {
		return err
	}
	tasks, err := loadTasks(path)
	if err != nil {
		return err
	}
	i := findTask(tasks, id)
	if i < 0 {
		return fmt.Errorf("no task with id %d", id)
	}
	removed := tasks[i]
	tasks = append(tasks[:i], tasks[i+1:]...)
	if err := saveTasks(path, tasks); err != nil {
		return err
	}
	fmt.Printf("Removed task #%d: %s\n", removed.ID, removed.Title)
	return nil
}

func parseID(args []string) (int64, error) {
	if len(args) != 1 {
		return 0, fmt.Errorf("expected a single task id")
	}
	id, err := strconv.ParseInt(args[0], 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid id %q", args[0])
	}
	return id, nil
}

func usage() {
	fmt.Fprintln(os.Stderr, "Usage: todo2 <command> [args]")
	fmt.Fprintln(os.Stderr, "Commands:")
	fmt.Fprintln(os.Stderr, "  add <title>           add a new task")
	fmt.Fprintln(os.Stderr, "  list                  list all tasks")
	fmt.Fprintln(os.Stderr, "  done <id>             mark a task as done")
	fmt.Fprintln(os.Stderr, "  rm <id>               remove a task")
}

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(1)
	}

	var err error
	switch os.Args[1] {
	case "add":
		err = cmdAdd(os.Args[2:])
	case "list":
		err = cmdList(os.Args[2:])
	case "done":
		err = cmdDone(os.Args[2:])
	case "rm":
		err = cmdRm(os.Args[2:])
	default:
		fmt.Fprintf(os.Stderr, "Unknown command %q\n", os.Args[1])
		usage()
		os.Exit(1)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}
